mapper.update:
UPDATE TB_USER_MANAGE
SET STATUS = 'ACTIVE',

    UPDATED_AT = NOW(),
    UPDATED_BY = #{USER_DETAILS.user.user_id}
WHERE USER_ID = #{REQUEST_DTO.user_id}

UPDATE TB_USER_MANAGE
SET STATUS = 'REJECT',
    REJECTION_REASON = #{REQUEST_DTO.reason},

    UPDATED_AT = NOW(),
    UPDATED_BY = #{USER_DETAILS.user.user_id}
WHERE USER_ID = #{REQUEST_DTO.user_id}

UPDATE TB_USER_MANAGE
SET STATUS     = #{REQUEST_DTO.status},

    UPDATED_AT = NOW(),
    UPDATED_BY = #{USER_DETAILS.user.user_id}
WHERE USER_IO = #{USER_ID}
